INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Abstract Factory-Pattern nur für plattformunabhängige Systeme geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für andere komplexe Objekte nutzbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Abstract Factory-Pattern?', 3, '[{"text": "Komplexe Objekterstellung vereinfachen", "correct": true, "because": "Erzeugt Familien verwandter Objekte"}, {"text": "Datenfluss steuern", "correct": false, "because": "Nicht primär"}, {"text": "UI-Optimierung", "correct": false, "because": "Kein Design-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Abstract Factory-Pattern?', 5, '[{"text": "Abstrakte Fabrik", "correct": true, "because": "Definiert Schnittstelle"}, {"text": "Konkrete Fabriken", "correct": true, "because": "Erzeugen Objekte"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Hardwareknoten", "correct": false, "because": "Kein Pattern-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Pattern erzeugt Objektfamilien. b) Es ersetzt einzelne Klassen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzt, nicht ersetzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Abstract Factory-Pattern?', 4, '[{"text": "Abstrakte Schnittstelle", "correct": false, "because": "Kern des Patterns"}, {"text": "Konkrete Produkte", "correct": false, "because": "Ergebnisse der Fabrik"}, {"text": "UI-Gestaltung", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Abstract Factory-Pattern auch ohne Abstraktion funktioniert?', 2, '[{"text": "Nein", "correct": true, "because": "Abstraktion ist zentral"}, {"text": "Ja", "correct": false, "because": "Ohne Abstraktion kein Pattern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die abstrakte Fabrik?', 3, '[{"text": "Schnittstelle definieren", "correct": true, "because": "Standardisiert Objekterstellung"}, {"text": "Daten speichern", "correct": false, "because": "Nicht primär"}, {"text": "UI rendern", "correct": false, "because": "Kein UI-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zum Abstract Factory-Pattern?', 5, '[{"text": "Abstrakte Produkte", "correct": true, "because": "Schnittstellen für Objekte"}, {"text": "Konkrete Fabriken", "correct": true, "because": "Erzeugen spezifische Objekte"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das Pattern erzeugt konsistente Objekte. b) Es ist nur für UI-Systeme. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht UI-spezifisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das Abstract Factory-Pattern?', 4, '[{"text": "Abstrakte Fabrik", "correct": false, "because": "Definiert Schnittstelle"}, {"text": "Konkrete Produkte", "correct": false, "because": "Ergebnisse der Erstellung"}, {"text": "3D-Grafiken", "correct": true, "because": "Kein Pattern-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Abstract Factory-Pattern nur für plattformübergreifende Systeme?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere komplexe Objekte"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehungen nutze ich im Abstract Factory-Pattern?', 4, '[{"text": "Abstrakte Schnittstelle", "correct": true, "because": "Zwischen Fabrik und Produkten"}, {"text": "Implementierung", "correct": true, "because": "Konkrete Fabriken zu Produkten"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Abstract Factory-Pattern die Leistung senkt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Overhead meist minimal"}, {"text": "Ja", "correct": false, "because": "Abhängig von Implementierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Abstract Factory-Pattern?', 3, '[{"text": "Konsistenz der Objekte", "correct": true, "because": "Familien einheitlich"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Struktur zählt mehr"}, {"text": "UI-Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es erzeugt verwandte Objekte. b) Es ist für Einzelobjekte besser als Factory Method.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einzelobjekte sind Factory Method"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Abstract Factory-Pattern?', 5, '[{"text": "Plattformunabhängigkeit", "correct": true, "because": "Familien konsistent"}, {"text": "Abstraktion", "correct": true, "because": "Vereinfacht Erstellung"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "UI-Verbesserung", "correct": false, "because": "Kein UI-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Abstract Factory-Pattern unwichtig?', 3, '[{"text": "Abstrakte Produkte", "correct": false, "because": "Definiert Objekte"}, {"text": "Konkrete Fabriken", "correct": false, "because": "Erzeugen Objekte"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann das Abstract Factory-Pattern auch einfache Objekte erzeugen?', 3, '[{"text": "Ja", "correct": true, "because": "Flexibel einsetzbar"}, {"text": "Nein", "correct": false, "because": "Nicht nur komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Abstract Factory-Pattern für Tests hilft?', 2, '[{"text": "Ja", "correct": true, "because": "Mock-Objekte erzeugbar"}, {"text": "Nein", "correct": false, "because": "Testfälle unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für die abstrakte Fabrik?', 4, '[{"text": "Interface", "correct": true, "because": "Definiert Erstellungsmethoden"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}, {"text": "UI-Komponente", "correct": false, "because": "Nicht UI-bezogen"}]');
